#!/usr/bin/env python
import sys


def solve(A: int, B: int, C: int, D: int, E: int):
    p = [A,B,C,D,E]
    list = []
    for d in p:
        diff = 10 - d % 10
        if diff == 10:
            diff = 0
        list.append((diff,d))
    list.sort()
    sum = 0
    for i in range(4):
        sum += list[i][0] + list[i][1]

    print(sum + list[4][1])
    return


# Generated by 1.1.3 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    A = int(next(tokens))  # type: int
    B = int(next(tokens))  # type: int
    C = int(next(tokens))  # type: int
    D = int(next(tokens))  # type: int
    E = int(next(tokens))  # type: int
    solve(A, B, C, D, E)

if __name__ == '__main__':
    main()
